from rest_framework.views import APIView
from rest_framework.response import Response
from rest_framework import permissions, status
from push_notifications.models import GCMDevice

class DeviceTopicSubscriptionView(APIView):
    permission_classes = [permissions.IsAuthenticated]

    def patch(self, request, pk):
        topics = request.data.get("topics", [])
        # Scope update strictly to devices owned by the authenticated caller
        device = GCMDevice.objects.filter(
            pk=pk,
            user=request.user
        ).first()
        if not device:
            return Response({"error": "Device not found or unauthorized"}, status=status.HTTP_404_NOT_FOUND)

        device.extra = {"topics": topics}
        device.save(update_fields=["extra"])
        return Response({"status": "Topics updated", "topics": topics}, status=status.HTTP_200_OK)
